package com.clara.memory.semantic.api;
import java.util.*;
public final class SemanticMemoryQuery {private final String tenantId,userId,conversationId,domain;private final float[] vector;private final int topK;private final double minScore;private final long now;private final Map<String,String> filters;
 public SemanticMemoryQuery(String tenant,String user,String conversation,String domain,float[] vector,int topK,double minScore,long now,Map<String,String> filters){if(tenant==null||tenant.trim().isEmpty()||vector==null||vector.length==0||topK<=0||Double.isNaN(minScore)||minScore<-1||minScore>1||now<0)throw new IllegalArgumentException("semantic query is invalid");tenantId=tenant;userId=user;conversationId=conversation;this.domain=domain;this.vector=vector.clone();double norm=0;for(float value:this.vector){if(Float.isNaN(value)||Float.isInfinite(value))throw new IllegalArgumentException("query vector is invalid");norm+=(double)value*value;}if(norm==0)throw new IllegalArgumentException("query vector must not be zero");this.topK=topK;this.minScore=minScore;this.now=now;LinkedHashMap<String,String> copied=new LinkedHashMap<String,String>();if(filters!=null)for(Map.Entry<String,String> value:filters.entrySet()){if(value.getKey()==null||value.getValue()==null)throw new IllegalArgumentException("metadata filter is invalid");copied.put(value.getKey(),value.getValue());}this.filters=Collections.unmodifiableMap(copied);}
 public String getTenantId(){return tenantId;}public String getUserId(){return userId;}public String getConversationId(){return conversationId;}public String getDomain(){return domain;}public float[] getVector(){return vector.clone();}public int getTopK(){return topK;}public double getMinScore(){return minScore;}public long getNowEpochMillis(){return now;}public Map<String,String> getMetadataFilters(){return filters;}}
